const scoredItems = [];

for (let i = 0; i < $input.all().length; i++) {
  const groqItem = $input.all()[i].json;
  const original = $('Normalize & Merge Feeds').all()[i]?.json || {};

  let score = 5;
  let reasoning = '';

  try {
    const rawContent = groqItem.choices?.[0]?.message?.content || '{}';
    const parsed = JSON.parse(rawContent);
    score = parseInt(parsed.relevance_score, 10) || 5;
    reasoning = parsed.reasoning || '';
  } catch (e) {
    const match = (groqItem.choices?.[0]?.message?.content || '').match(/relevance_score["\s:]+(\d+)/i);
    if (match) score = parseInt(match[1], 10);
  }

  scoredItems.push({
    json: {
      source: original.source,
      title: original.title,
      item_url: original.item_url,
      author: original.author,
      content_snippet: original.content_snippet,
      relevance_score: score,
      scoring_reason: reasoning
    }
  });
}

return scoredItems;

