const items = $input.all();
const today = new Date().toISOString().split('T')[0];

let message = `⚡ <b>ECHOAGENT AI RESEARCH DIGEST</b> ⚡\n`;
message += `📅 <b>Date:</b> <code>${today}</code>\n`;
message += `📊 <b>Status:</b> ${items.length} Qualified Breakthroughs Discovered\n\n`;

for (let i = 0; i < items.length; i++) {
  const groqRes = items[i].json;
  const original = $('Filter High Relevance').all()[i]?.json || {};

  let summary = 'Summary unavailable.';
  let why = '';

  try {
    const raw = groqRes.choices?.[0]?.message?.content || '{}';
    const parsed = JSON.parse(raw);
    summary = parsed.ai_summary || summary;
    why = parsed.why_it_matters || '';
  } catch (e) {
    summary = groqRes.choices?.[0]?.message?.content || summary;
  }

  const sourceIcons = { arxiv: '📄 [arXiv]', hackernews: '💬 [Hacker News]', rss: '📰 [Blog]' };
  const icon = sourceIcons[original.source] || '📌';
  const score = original.relevance_score || 8;

  message += `━━━━━━━━━━━━━━━━━━━━━\n`;
  message += `${icon} <b>${i + 1}. ${original.title || 'Untitled'}</b>\n`;
  message += `⭐ <b>Relevance:</b> <code>${score}/10</code>\n\n`;
  message += `📝 <b>Summary:</b> ${summary}\n\n`;
  if (why) {
    message += `💡 <b>Why it matters:</b> <i>${why}</i>\n\n`;
  }
  if (original.item_url) {
    message += `🔗 <a href="${original.item_url}">Read Original Article</a>\n\n`;
  }
}

message += `━━━━━━━━━━━━━━━━━━━━━\n🚀 <i>Delivered autonomously by EchoAgent</i>`;

return [{ json: { digest_html: message } }];
